const fuentes = [
  { url: 'https://news.mit.edu/topic/mitartificial-intelligence2-rss.xml', source: 'MIT News AI' },
  { url: 'https://sloanreview.mit.edu/feed/', source: 'MIT Sloan Review' },
  { url: 'https://www.cio.com/feed/', source: 'CIO.com' },
  { url: 'https://www.wired.com/feed/tag/ai/latest/rss', source: 'Wired AI' },
  { url: 'https://www.wired.com/feed/category/business/latest/rss', source: 'Wired Business' },
  { url: 'https://www.wired.com/feed/category/science/latest/rss', source: 'Wired Science' }
];
return fuentes.map(f => ({ json: f }));

// Parsear XML RSS a JSON limpio
const items = $input.all();
const articulos = [];

for (const item of items) {
  const xml = typeof item.json.data === 'string' ? item.json.data : '';
  const source = item.json.source || '';
  if (!xml) continue;

  const regex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = regex.exec(xml)) !== null) {
    const block = match[1];
    const tag = (name) => {
      const m = block.match(new RegExp('<' + name + '[^>]*>([\\s\\S]*?)</' + name + '>', 'i'));
      if (!m) return '';
      return m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/<[^>]+>/g, '').trim();
    };
    const title = tag('title');
    const link = tag('link') || tag('guid');
    if (title && link) {
      articulos.push({ title, link, description: tag('description').substring(0, 600), pubDate: tag('pubDate'), source });
    }
  }
}

// Deduplicar por URL
const seen = new Set();
const unicos = articulos.filter(a => { if (seen.has(a.link)) return false; seen.add(a.link); return true; });

return [{ json: { articulos: unicos, total: unicos.length } }];

// ========================================
// CAPA 2: CONTEXT GRAPH → RAG
// ========================================
// ORDEN: Context Graph PRIMERO, RAG DESPUES
// El Context Graph da memoria (que se publico)
// El RAG da identidad (como debe verse)
// ========================================

const items = $input.all();
let articulosNuevos = [];
const topicosPublicados = new Set();

for (const item of items) {
  if (item.json.articulos) {
    articulosNuevos = item.json.articulos;
  } else if (item.json.topic) {
    topicosPublicados.add(item.json.topic?.toLowerCase().trim());
  }
}

// CONTEXT GRAPH: filtrar lo ya publicado
const filtrados = articulosNuevos.filter(a => {
  const t = a.title.toLowerCase();
  for (const pub of topicosPublicados) {
    if (pub && t.includes(pub)) return false;
  }
  return true;
});

if (filtrados.length === 0) {
  return [{ json: { _sin_noticias: true } }];
}

// RAG: Identidad de marca
const RAG = {
  marca: 'Aura Studio',
  filosofia: 'Work fast, live slow',
  tono: 'Reflexivo, sofisticado, humano, calido. Sin relleno.',
  prohibido: 'Tech bros, vendedores agresivos, emojis excesivos, clickbait',
  estetica: {
    fondos: 'Fotografia cinematografica editorial, naturaleza latinoamericana, golden hour o neblina',
    paleta_hex: { verde_profundo: '#1B4332', crema: '#F5F0E8', beige: '#D4A574', dorado: '#C9A96E', oscuro: '#1A1A2E' },
    prohibido_visual: 'Robots, circuitos, neon, cyberpunk, oficinas genericas, texto en imagenes generadas'
  },
  tipografia: { titulos: 'Kaneda Gothic Bold', cuerpo: 'Inter Regular' },
  logo: { posicion: 'bottom_right', variantes: { claro: 'logo_cream.png', oscuro: 'logo_green.png' } },
  cta_permitidos: ['comenta', 'guarda', 'comparte'],
  formato: '5-6 slides, cada slide es: titulo + cuerpo + footer + fondo separado'
};

return [{ json: {
  articulos: filtrados.slice(0, 10),
  context_graph: { publicados: Array.from(topicosPublicados), total: topicosPublicados.size },
  rag: RAG
}}];

