// ========================================
// GUARDRAILS v3: Validar schema desacoplado
// ========================================

const aiRaw = $input.first().json;
let carrusel;

try {
  const content = aiRaw.choices?.[0]?.message?.content || aiRaw.message?.content || aiRaw.text || '';
  const m = content.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Sin JSON');
  carrusel = JSON.parse(m[0]);
} catch (e) {
  return [{ json: { _error: true, msg: 'Error parseando AI: ' + e.message } }];
}

const problemas = [];
const slides = carrusel.slides || [];

// G1: 5-6 slides
if (slides.length < 5) problemas.push('Solo ' + slides.length + ' slides (minimo 5)');
if (slides.length > 6) { carrusel.slides = slides.slice(0, 6); problemas.push('Recortado a 6 slides'); }

// G2: Cada slide debe tener las 3 capas de texto
for (const s of carrusel.slides) {
  if (!s.layer_title_text) problemas.push('Slide ' + s.number + ': falta layer_title_text');
  if (s.layer_title_text && s.layer_title_text.split(/\s+/).length > 10) {
    problemas.push('Slide ' + s.number + ': titulo excede 10 palabras');
  }
  if (s.layer_body_text && s.layer_body_text.split(/\s+/).length > 30) {
    problemas.push('Slide ' + s.number + ': body excede 30 palabras');
  }
  if (!s.layer_footer_text) s.layer_footer_text = 'AURA STUDIO';
}

// G3: Background prompts NO deben contener texto/tipografia
const textoProhibido = ['text overlay', 'typography', 'letters', 'words', 'headline', 'title text'];
const visualProhibido = ['robot', 'circuit', 'neon', 'cyberpunk', 'matrix', 'motherboard', 'generic office'];

for (const s of carrusel.slides) {
  if (!s.background_image_prompt) {
    problemas.push('Slide ' + s.number + ': falta background_image_prompt');
    continue;
  }
  const lower = s.background_image_prompt.toLowerCase();

  // Forzar 'no text' si no esta
  if (!lower.includes('no text')) {
    s.background_image_prompt += ', no text, no typography, no letters';
    problemas.push('Slide ' + s.number + ': agregado "no text" al prompt');
  }

  // Remover estetica prohibida
  for (const p of visualProhibido) {
    if (lower.includes(p)) {
      s.background_image_prompt = s.background_image_prompt.replace(new RegExp(p, 'gi'), 'tropical nature');
      problemas.push('Slide ' + s.number + ': reemplazado "' + p + '"');
    }
  }
}

// G4: Design settings presentes
if (!carrusel.design_settings) {
  carrusel.design_settings = {
    template_id: 'aura_carousel_v1',
    primary_color: '#1B4332',
    accent_color: '#D4A574',
    background_color: '#1A1A2E',
    font_title: 'Kaneda Gothic Bold',
    font_body: 'Inter Regular',
    logo_variant: 'cream',
    logo_position: 'bottom_right'
  };
  problemas.push('design_settings ausente, aplicado default');
}

// G5: Hashtags obligatorios
if (!carrusel.hashtags) carrusel.hashtags = [];
if (!carrusel.hashtags.some(h => h.toLowerCase().includes('aurastudio'))) carrusel.hashtags.unshift('#AuraStudio');
if (!carrusel.hashtags.some(h => h.toLowerCase().includes('workfastliveslow'))) carrusel.hashtags.splice(1, 0, '#WorkFastLiveSlow');

// G6: CTA valido
if (!['comenta', 'guarda', 'comparte'].includes((carrusel.cta || '').toLowerCase())) {
  carrusel.cta = 'comenta';
}

// --- Telegram Preview ---
let msg = '🎨 *CARRUSEL GENERADO (v3 - Template Pipeline)*\n\n';
msg += '📰 *' + (carrusel.meta?.topic || '?') + '*\n';
msg += '🔗 ' + (carrusel.meta?.source || '') + '\n';
msg += '⚡ ' + (carrusel.meta?.urgency || '-') + '\n\n';
msg += '🎨 *Template:* ' + carrusel.design_settings.template_id + '\n';
msg += '🎨 *Colores:* ' + carrusel.design_settings.primary_color + ' / ' + carrusel.design_settings.accent_color + '\n\n';
msg += '📑 *Slides:*\n';
for (const s of carrusel.slides) {
  msg += s.number + '. *' + s.layer_title_text + '*\n';
  if (s.layer_body_text) msg += '   ' + s.layer_body_text.substring(0, 60) + '\n';
  msg += '   🖼 _' + s.background_image_prompt.substring(0, 50) + '..._\n';
}
msg += '\n✍️ ' + (carrusel.caption || '') + '\n';
msg += '#️⃣ ' + carrusel.hashtags.join(' ') + '\n';

if (problemas.length > 0) {
  msg += '\n⚠️ *Guardrails:*\n';
  problemas.forEach(p => { msg += '  • ' + p + '\n'; });
}
msg += '\n---\n✅ *APROBAR* | ❌ *RECHAZAR* | 🔄 *REGENERAR*';

return [{ json: {
  carrusel,
  carrusel_json: JSON.stringify(carrusel),
  telegram_msg: msg,
  rejected: carrusel.rejected_articles || [],
  guardrail_issues: problemas
}}];

// ========================================
// Separar slides para generacion de fondos
// Cada slide se convierte en un item individual
// para que el HTTP Request genere un fondo por slide
// ========================================
const data = $input.first().json;
const slides = data.carrusel?.slides || [];

return slides.map(s => ({
  json: {
    slide_number: s.number,
    prompt: s.background_image_prompt,
    size: '1024x1024'
  }
}));

// ========================================
// Compilar fondos generados + datos del carrusel
// Preparar payload para la API de renderizado
// ========================================
const bgItems = $input.all();
const carruselData = $('7. Guardrails').first().json;
const carrusel = carruselData.carrusel;

// Mapear URLs de fondo a cada slide
const slidesConFondo = (carrusel.slides || []).map((slide, i) => {
  const bg = bgItems[i]?.json;
  const bgUrl = bg?.data?.[0]?.url || bg?.data?.[0]?.b64_json || 'PENDIENTE_GENERAR';
  return {
    ...slide,
    background_image_url: bgUrl
  };
});

// Construir payloads para Bannerbear/Creatomate
const renderPayloads = slidesConFondo.map(s => ({
  template: carrusel.design_settings?.template_id || 'aura_carousel_v1',
  modifications: [
    { name: 'title', text: s.layer_title_text, color: carrusel.design_settings?.primary_color },
    { name: 'body', text: s.layer_body_text || '', color: null },
    { name: 'footer', text: s.layer_footer_text || 'AURA STUDIO', color: null },
    { name: 'background', image_url: s.background_image_url }
  ],
  metadata: {
    slide_number: s.number,
    slide_type: s.type
  }
}));

return [{ json: {
  carrusel_completo: { ...carrusel, slides: slidesConFondo },
  render_payloads: renderPayloads,
  carrusel_json: JSON.stringify({ ...carrusel, slides: slidesConFondo }),
  telegram_msg: carruselData.telegram_msg,
  rejected: carruselData.rejected
}}];

// Guardar rechazados en buffer para recap semanal
const data = $('10. Compilar para Render').first().json;
const rejected = data.rejected || [];

if (rejected.length === 0) return [{ json: { _skip: true, telegram_msg: data.telegram_msg } }];

return rejected.map(r => ({
  json: {
    topic: r.title || '', date: new Date().toISOString(),
    source_url: r.url || '', status: 'rejected',
    angle: r.reason || '', carrusel_json: ''
  }
}));

const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message?.chat?.id || 'TU_CHAT_ID';
const pendientes = items.filter(i => i.json.status === 'pending');
const ultimo = pendientes[pendientes.length - 1];
if (!ultimo) return [{ json: { chat_id: chatId, topic: '', msg: '⚠️ No hay carrusel pendiente.' } }];
return [{ json: { chat_id: chatId, topic: ultimo.json.topic, msg: '✅ *Aprobado:* ' + ultimo.json.topic + '\n\nContext Graph actualizado.\n🌿 _Work fast, live slow_' } }];

const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message?.chat?.id || 'TU_CHAT_ID';
const pendientes = items.filter(i => i.json.status === 'pending');
const ultimo = pendientes[pendientes.length - 1];
if (!ultimo) return [{ json: { chat_id: chatId, topic: '', msg: '⚠️ Nada pendiente.' } }];
return [{ json: { chat_id: chatId, topic: ultimo.json.topic, msg: '❌ *Rechazado:* ' + ultimo.json.topic + '\nMovido al buffer del recap semanal.\n\n🔄 Escribe REGENERAR para nueva version.' } }];

const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message?.chat?.id || 'TU_CHAT_ID';
const pendientes = items.filter(i => (i.json.status === 'pending' || i.json.status === 'rejected') && i.json.carrusel_json);
const ultimo = pendientes[pendientes.length - 1];
if (!ultimo) return [{ json: { chat_id: chatId, _error: true, msg: '⚠️ Nada para regenerar.' } }];
let prev; try { prev = JSON.parse(ultimo.json.carrusel_json); } catch(e) { prev = {}; }
return [{ json: { chat_id: chatId, topic: ultimo.json.topic, source: ultimo.json.source || '', prev } }];

