const aiRaw = $input.first().json;
const prev = $('Preparar Regen').first().json;
let c;
try {
  const content = aiRaw.choices?.[0]?.message?.content || '';
  c = JSON.parse(content.match(/\{[\s\S]*\}/)[0]);
} catch (e) {
  return [{ json: { chat_id: prev.chat_id, msg: '⚠️ Error regenerando.' } }];
}
// Quick guardrails
for (const s of (c.slides || [])) {
  if (s.background_image_prompt && !s.background_image_prompt.toLowerCase().includes('no text')) {
    s.background_image_prompt += ', no text, no typography';
  }
}
if (!c.hashtags?.some(h => h.includes('AuraStudio'))) { c.hashtags = c.hashtags || []; c.hashtags.unshift('#AuraStudio'); }
let msg = '🔄 *REGENERADO*\n\n';
for (const s of (c.slides || [])) { msg += s.number + '. *' + s.layer_title_text + '*\n'; }
msg += '\n✍️ ' + (c.caption || '') + '\n---\n✅ *APROBAR* | ❌ *RECHAZAR* | 🔄 *REGENERAR*';
return [{ json: { chat_id: prev.chat_id, topic: prev.topic, carrusel_json: JSON.stringify(c), msg } }];

const items = $input.all();
const hace7d = new Date(Date.now() - 7*24*60*60*1000);
const rechazados = items.filter(i => i.json.status === 'rejected' && new Date(i.json.date) >= hace7d);
if (rechazados.length === 0) return [{ json: { _sin_recap: true } }];
return [{ json: { rechazados: rechazados.map(r => ({ topic: r.json.topic, url: r.json.source_url, reason: r.json.angle })), total: rechazados.length } }];

const aiRaw = $input.first().json;
let c;
try {
  const content = aiRaw.choices?.[0]?.message?.content || '';
  c = JSON.parse(content.match(/\{[\s\S]*\}/)[0]);
} catch (e) { return [{ json: { msg: '⚠️ Error en recap.' } }]; }
for (const s of (c.slides || [])) {
  if (s.background_image_prompt && !s.background_image_prompt.toLowerCase().includes('no text')) {
    s.background_image_prompt += ', no text, no typography';
  }
}
let msg = '📋 *RECAP SEMANAL*\n\n';
for (const s of (c.slides || [])) { msg += s.number + '. *' + (s.layer_title_text || '') + '*\n'; }
msg += '\n---\n✅ *APROBAR* | ❌ *RECHAZAR* | 🔄 *REGENERAR*';
return [{ json: { carrusel_json: JSON.stringify(c), msg } }];
